"use client";

import React, { useState, useMemo } from "react";
import { motion, AnimatePresence } from "framer-motion";

export function ExpandableExcerpt({ text }: { text: string }) {
  const [expanded, setExpanded] = useState(false);

  return (
    <div>
      <motion.div
  initial={false}
  animate={{
    height: expanded ? "auto" : 72,
    opacity: 1,
  }}
  transition={{
    duration: 0.4,
    ease: "easeInOut",
  }}
  className="overflow-hidden"
>
        <p className="text-xs text-muted-text font-sans leading-relaxed whitespace-pre-line">
          {text}
        </p>
      </motion.div>

      {text.length > 140 && (
        <button
          onClick={(e) => {
            e.stopPropagation();
            setExpanded(!expanded);
          }}
          className="mt-2 text-accent-green text-[11px] font-semibold hover:underline transition"
        >
          {expanded ? "See Less ↑" : "See More ↓"}
        </button>
      )}
    </div>
  );
}